    {
        private void testRelations(BigInt a, BigInt b, bool isLessThan, bool isLessThanOrEqual, bool isGreaterThan, bool isGreaterThanOrEqual, bool isEqual, bool isNotEqual)
        {
            Assert.AreEqual(a < b, isLessThan);
            Assert.AreEqual(a <= b, isLessThanOrEqual);
            Assert.AreEqual(a > b, isGreaterThan);
            Assert.AreEqual(a >= b, isGreaterThanOrEqual);
            Assert.AreEqual(a == b, isEqual);
            Assert.AreEqual(a != b, isNotEqual);
        }

